		// 读工具：直接读内存 state.tables（不落盘、不写会话树），内容只进工具结果
		pi.registerTool({
			name: "table_list",
			label: "列出自定义表格",
			description:
				"List all custom tables: name, columns, row count, auto flag, description. Table content is never injected into context — read any table with table_query when you need its rows.",
			parameters: Type.Object({}),
			async execute() {
				const tables = state.tables ?? {};
				const names = Object.keys(tables);
				if (names.length === 0) {
					return { content: [{ type: "text", text: "尚无自定义表格。需要长期结构化的参考数据（物品/关系/时间线等）可先用 table_create 建表。" }] };
				}
				const lines = names.map((name) => {
					const t = tables[name];
					const cols = t.columns.map((c) => (c.type ? `${c.name}:${c.type}` : c.name)).join("、");
					const auto = t.auto ? "[auto] " : "";
					return `${auto}${name}（${cols}，${t.rows.length} 行）${t.description ? ` — ${t.description}` : ""}`;
