				snapshotState();
				const lines = [...(r.applied ?? []).map((a) => `✓ ${a}`), ...(r.warnings ?? []).map((w) => `⚠ ${w}`)];
				return {
					content: [{ type: "text", text: lines.join("\n") || "（无变更）" }],
					details: { state },
